pub struct CatalogList {
    /// 8 huruf pertama UUID Brave (stabil, dipakai sebagai kunci setelan).
    pub id: &'static str,
    /// (Indonesia, Inggris)
    pub title: (&'static str, &'static str),
    pub desc: &'static str,
    pub urls: &'static [&'static str],
    /// Nyala secara bawaan di Brave.
    pub default_on: bool,
    /// Daftar iklan situs bahasa tertentu.
    pub regional: bool,
    /// Daftar ini diatur setelan lama Ovner (bukan `filter_lists`).
    pub setting: Option<&'static str>,
}

