/// Nama berkas untuk sumber ke-`k` daftar `id`.
pub fn file_name(id: &str, k: usize) -> String {
    format!("opt-{}-{k}.txt", id.to_ascii_lowercase())
}

pub fn find(id: &str) -> Option<&'static CatalogList> {
    CATALOG.iter().find(|c| c.id.eq_ignore_ascii_case(id))
}

/// Daftar opsional yang nyala secara bawaan (selain yang diatur setelan lama).
pub fn default_ids() -> Vec<String> {
    CATALOG.iter().filter(|c| c.default_on && c.setting.is_none()).map(|c| c.id.to_string()).collect()
}
